<?php require 'config.php';require_login();if(is_admin()){header('Location: admin.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$m=trim($_POST['message']??'');if($m!==''){$s=$pdo->prepare("INSERT INTO messages(user_id,sender_role,message) VALUES(?,'customer',?)");$s->execute([$_SESSION['user_id'],$m]);header('Location: messages.php');exit;}}$s=$pdo->prepare("SELECT * FROM messages WHERE user_id=? ORDER BY created_at");$s->execute([$_SESSION['user_id']]);$msgs=$s->fetchAll();$page_title='Message JLB';require 'header.php';?><section class="wrap"><h1>Message the JLB team</h1><div style="background:white;padding:20px;max-width:750px"><?php foreach($msgs as $m):?><p><b><?=e(ucfirst($m['sender_role']))?>:</b> <?=e($m['message'])?> <small class="muted"><?=e($m['created_at'])?></small></p><?php endforeach;?><form method="post"><textarea name="message" required placeholder="Ask us about sizes, colours, orders, or products..."></textarea><button>Send message</button></form></div></section><?php require 'footer.php';?>
